    /** Ce inseamna codul, sau null daca nu e in nomenclator. */
    public static function descrie(string $cod): ?string
    {
        if (!isset(self::CODURI[$cod])) {
            return null;
        }

        [$denumire, $cota] = self::CODURI[$cod];

        return $cota === '' ? $denumire : $denumire . ' (' . $cota . '%)';
    }
